package com.example.ts15quarkusbanking.runtime;

import com.fasterxml.jackson.databind.DeserializationFeature;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.core.type.TypeReference;
import java.time.LocalDate;
import java.time.OffsetDateTime;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Map;
import java.util.regex.Pattern;

/**
 * What each operation of the service accepts and who may run it, from the features (generated by gherkin-ai).
 * Every stack embeds the same JSON and interprets it the same way.
 */
public final class Contracts {
    public record FieldContract(String name, List<String> rules) {
        public FieldContract {
            rules = rules == null ? List.of() : rules;
        }
    }

    /** isPublic: a read the feature allows without a signed-in user. */
    public record OperationContract(List<FieldContract> fields, List<String> roles, List<String> permissions, boolean deletes,
                                    @com.fasterxml.jackson.annotation.JsonProperty("public") boolean isPublic) {
        public OperationContract {
            fields = fields == null ? List.of() : fields;
            roles = roles == null ? List.of() : roles;
            permissions = permissions == null ? List.of() : permissions;
        }
    }

    /** grants: commands of a role aggregate and the role each one gives the user (assign_docente → docente). */
    public record AggregateContract(List<String> fields, Map<String, OperationContract> commands, OperationContract list, OperationContract get, Map<String, String> grants) {
        public AggregateContract {
            fields = fields == null ? List.of() : fields;
            commands = commands == null ? Map.of() : commands;
            grants = grants == null ? Map.of() : grants;
        }
    }

    /** Who calls: the roles and permissions of the validated token. */
    public record Caller(String subject, List<String> roles, List<String> permissions) {
        public Caller {
            roles = roles == null ? List.of() : roles;
            permissions = permissions == null ? List.of() : permissions;
        }
    }

    /** A field that breaks a rule, as the 422 response lists it. */
    public record FieldError(String field, String rule, String message) {}

    public static final class ForbiddenException extends RuntimeException {
        public ForbiddenException(String message) {
            super(message);
        }
    }

    /** The payload breaks the rules of the operation: 422 with the fields. */
    public static final class FieldValidationException extends RuntimeException {
        private final List<FieldError> errors;

        public FieldValidationException(List<FieldError> errors) {
            super(String.join("; ", errors.stream().map(FieldError::message).toList()));
            this.errors = List.copyOf(errors);
        }

        public List<FieldError> errors() {
            return errors;
        }
    }

    private static final ObjectMapper JSON = new ObjectMapper().configure(DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES, false);
    public static final Map<String, AggregateContract> ALL = parse(String.join("",
        "{\"PaymentExecution\":{\"fields\":[],\"commands\":{\"execute_payment\":{\"fields\":[],\"roles\":[],\"permissions\":[],\"deletes\":false}},\"list\":{\"roles\":[],\"permissions\":[],\"public\":false},\"get\":{\"roles\":[],\"permissions\":[],\"public\":false},\"grants\":{}}}"
    ));
    /** Fields that are secrets (a password): validated, never stored in the read model or the events. */
    public static final Pattern SECRET = Pattern.compile("^(password|password_confirmation|current_password|new_password|passwd|secret|token|api_key|apikey)$", Pattern.CASE_INSENSITIVE);
    private static final Pattern EMAIL = Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
    private static final Pattern UUID_PATTERN = Pattern.compile("^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$", Pattern.CASE_INSENSITIVE);

    private Contracts() {}

    private static Map<String, AggregateContract> parse(String json) {
        try {
            return JSON.readValue(json, new TypeReference<Map<String, AggregateContract>>() {});
        } catch (Exception e) {
            throw new IllegalStateException("Invalid contract JSON", e);
        }
    }

    public static OperationContract command(String aggregateType, String command) {
        AggregateContract a = ALL.get(aggregateType);
        return a == null ? null : a.commands().get(command);
    }

    /** Throws ForbiddenException unless the caller has one of the roles and one of the permissions the operation names. */
    public static void authorize(OperationContract op, Caller caller, String what) {
        if (op == null || caller == null) return;
        if (!op.roles().isEmpty() && op.roles().stream().noneMatch(caller.roles()::contains)) throw new ForbiddenException(what + " requires the role " + String.join(" or ", op.roles()));
        if (!op.permissions().isEmpty() && op.permissions().stream().noneMatch(caller.permissions()::contains)) throw new ForbiddenException(what + " requires the permission " + String.join(" or ", op.permissions()));
    }

    private static boolean empty(Object v) {
        return v == null || "".equals(v);
    }

    private static boolean whole(Object v) {
        Double d = number(v);
        return d != null && d == Math.floor(d);
    }

    private static Double number(Object v) {
        if (v instanceof Boolean) return null;
        if (v instanceof Number n) return n.doubleValue();
        if (v instanceof String s) {
            try {
                return Double.parseDouble(s.trim());
            } catch (NumberFormatException e) {
                return null;
            }
        }
        return null;
    }

    private static double size(Object v) {
        if (v instanceof String s) return s.length();
        if (v instanceof List<?> l) return l.size();
        Double n = number(v);
        return n == null ? 0 : n;
    }

    private static boolean isDate(Object v) {
        if (!(v instanceof String s)) return false;
        try {
            LocalDate.parse(s);
            return true;
        } catch (Exception e) {
            try {
                OffsetDateTime.parse(s);
                return true;
            } catch (Exception e2) {
                return false;
            }
        }
    }

    /** The errors of a payload against the fields of an operation (empty when it is valid). */
    public static List<FieldError> fieldErrors(OperationContract op, Map<String, Object> payload) {
        List<FieldError> errors = new ArrayList<>();
        if (op == null) return errors;
        for (FieldContract f : op.fields()) {
            Object v = payload.get(f.name());
            if (empty(v)) {
                if (f.rules().contains("required")) errors.add(new FieldError(f.name(), "required", f.name() + " is required"));
                continue;
            }
            for (String rule : f.rules()) {
                int sp = rule.indexOf(' ');
                String name = sp < 0 ? rule : rule.substring(0, sp);
                String param = sp < 0 ? "" : rule.substring(sp + 1);
                Double n = number(param);
                String problem = switch (name) {
                    case "string" -> v instanceof String ? null : "must be a text";
                    case "integer" -> whole(v) ? null : "must be a whole number";
                    case "numeric" -> number(v) != null ? null : "must be a number";
                    case "boolean" -> v instanceof Boolean || List.of("0", "1", "true", "false").contains(String.valueOf(v)) ? null : "must be true or false";
                    case "email" -> v instanceof String s && EMAIL.matcher(s).matches() ? null : "must be a valid email";
                    case "uuid" -> v instanceof String s && UUID_PATTERN.matcher(s).matches() ? null : "must be a valid identifier";
                    case "date" -> isDate(v) ? null : "must be a valid date";
                    case "array" -> v instanceof List<?> ? null : "must be a list";
                    case "max" -> n != null && size(v) > n ? "must be at most " + param : null;
                    case "min" -> n != null && size(v) < n ? "must be at least " + param : null;
                    case "enum" -> Arrays.asList(param.split(",")).contains(String.valueOf(v)) ? null : "must be one of " + param;
                    default -> null;
                };
                if (problem != null) errors.add(new FieldError(f.name(), name, f.name() + " " + problem));
            }
        }
        return errors;
    }

    /** Throws FieldValidationException (422) when the payload breaks the operation's rules. */
    public static void validate(OperationContract op, Map<String, Object> payload) {
        List<FieldError> errors = fieldErrors(op, payload);
        if (!errors.isEmpty()) throw new FieldValidationException(errors);
    }
}
